python3 - <<'PY'
import subprocess
branches=['rachel','monica','phoebe','joey','chandler','ross']
for ep in ['S06/E15','S06/E16']:
    count=0
    for b in branches:
        shas=subprocess.check_output(['git','rev-list','origin/friend/'+b],text=True).split()
        for sha in shas:
            msg=subprocess.check_output(['git','show','-s','--format=%B',sha],text=True)
            if 'Friend-Message: 1' in msg and ('Episode: '+ep in msg):
                count+=1
    print(ep,count)
PY
